"""Rendering and recognition of common fragments in diagnostic output.

Each recognizer owns the pieces that it finds. Later recognizers work only on
unclaimed pieces, so lower-level tokens never repaint a larger structure.
"""
import re
import json
import math
import ipaddress
from dataclasses import dataclass

COLORS = {'default':39,'black':30,'red':31,'green':32,'yellow':33,
          'blue':34,'magenta':35,'cyan':36,'white':37,
          'bright_black':90,'bright_red':91,'bright_green':92,
          'bright_yellow':93,'bright_blue':94,'bright_magenta':95,
          'bright_cyan':96,'bright_white':97}

@dataclass
class Style:
    fg: str = None
    bg: str = None
    bold: bool = False
    faint: bool = False
    italic: bool = False
    underline: bool = False

    def paint(self, text, pad=False):
        codes = []
        for name, code in [('bold',1),('faint',2),('italic',3),('underline',4)]:
            if getattr(self,name):
                codes.append(str(code))
        if self.bg is not None:
            codes.append(str(COLORS[self.bg]+10))
        if self.fg is not None:
            codes.append(str(COLORS[self.fg]))
        if not codes:
            return text
        if pad and self.bg is not None:
            text = ' '+text+' '
        return '\x1b['+';'.join(codes)+'m'+text+'\x1b[0m'


def default_styles():
    return {
        'numbers': {'number':Style(fg='cyan')},
        'dates': {'date':Style(fg='magenta'),'time':Style(fg='blue'),
                  'separator':Style(faint=True),'zone':Style(fg='red')},
        'ip_addresses':{'number':Style(fg='blue',italic=True),
                        'letter':Style(fg='magenta',italic=True),'separator':Style(fg='red')},
        'urls': {'http':Style(fg='red',faint=True),'https':Style(fg='green',faint=True),
                 'host':Style(fg='blue',faint=True),'path':Style(fg='blue'),
                 'symbols':Style(fg='red')},
        'url_queries': {'key':Style(fg='magenta'),'value':Style(fg='cyan'),
                        'separator':Style(fg='red')},
        'key_value_pairs':{'key':Style(faint=True),'separator':Style(fg='white')},
        'paths':{'segment':Style(fg='green'),'separator':Style(fg='yellow')},
        'pointers':{'number':Style(fg='blue',italic=True),'letter':Style(fg='magenta',italic=True),
                    'x':Style(fg='red'),'separator':Style(faint=True)},
        'uuids':{'number':Style(fg='blue',italic=True),'letter':Style(fg='magenta',italic=True),
                 'dash':Style(fg='red')},
        'processes':{'name':Style(fg='yellow'),'id':Style(fg='cyan'),'bracket':Style(fg='red')},
        'quotes':{'style':Style(fg='yellow')},
        'json':{'key':Style(faint=True),'colon':Style(faint=True),'comma':Style(faint=True),
                'square_bracket':Style(faint=True),'curly_bracket':Style(faint=True),
                'quotes':Style(faint=True)},
    }

GROUPS = ['numbers','urls','pointers','dates','paths','quotes','key-value-pairs',
          'uuids','ip-addresses','processes','json']

# Deliberately ASCII: in log records the punctuation surrounding an identifier
# includes Unicode letters as well as ordinary punctuation.
ASCII = re.ASCII
DAY = r'(?:0[1-9]|[12][0-9]|3[01])'
YEAR = r'(?:19|20)[0-9]{2}'
DATE_RE = re.compile(r'('+YEAR+r')([-/])('+DAY+r')([-/])('+DAY+r')|('
                     +DAY+r')([-/])('+DAY+r')([-/])('+YEAR+r')')
TIME_RE = re.compile(r'([T\s]?)([01]?[0-9]|2[0-3])(:)([0-5][0-9])(:)([0-5][0-9])([.,:]?)([0-9]*)(Z?)', ASCII)
V4_RE = re.compile(r'\b[0-9]{1,3}(?:\.[0-9]{1,3}){3}\b(?:/[0-9]{1,2}\b)?',ASCII)
V6_RE = re.compile(r'[A-Fa-f0-9:.]{3,}(?:/[0-9]{1,3}\b)?',ASCII)
KV_RE = re.compile(r'(^|\s)([A-Za-z0-9_]+)(=)',ASCII)
PATH_RE = re.compile(r'(?:~|[A-Za-z0-9_.-]+|/)?(?:/[A-Za-z0-9_.-]+){2,}',ASCII)
POINTER_RE = re.compile(r'\b0[xX](?:[A-Fa-f0-9]{16}|[A-Fa-f0-9]{8})\b',ASCII)
UUID_RE = re.compile(r'\b[A-Fa-f0-9]{8}(?:-[A-Fa-f0-9]{4}){3}-[A-Fa-f0-9]{12}\b',ASCII)
PROCESS_RE = re.compile(r'([A-Za-z0-9_/-]+)\[([0-9]+)\]',ASCII)
NUMBER_RE = re.compile(r'\b[0-9]+(?:\.[0-9]+)?\b',ASCII)
URL_RE = re.compile(r'(https?)://([A-Za-z0-9_.-]+)(/[A-Za-z0-9_.~/%+\-]*)?([?&][A-Za-z0-9_.~%+?&=\-]*)?',ASCII)
QUERY_RE = re.compile(r'([?&])([A-Za-z0-9_.~%+\-]*)(=)([A-Za-z0-9_.~%+\-]*)',ASCII)

class JsonNumber:
    def __init__(self, s):
        self.raw = s


def json_number(s):
    # JSON integers have signed/unsigned 64-bit representations. Other numbers
    # go through the floating-point representation before being displayed.
    try:
        n=int(s)
        integer='.' not in s and 'e' not in s.lower() and s!='-0'
    except ValueError:
        n=0;integer=False
    if integer and -(2**63)<=n<2**64:
        return str(n)
    f=float(s)
    if not math.isfinite(f):
        raise ValueError('number out of range')
    t=repr(f).lower()
    if 'e' not in t:
        return t
    mant, exponent=t.split('e'); exponent=int(exponent)
    if -5 <= exponent < 16:
        negative=mant.startswith('-')
        if negative: mant=mant[1:]
        a,_,b=mant.partition('.')
        digits=a+b
        point=len(a)+exponent
        if point<=0: res='0.'+'0'*(-point)+digits
        elif point>=len(digits):res=digits+'0'*(point-len(digits))+'.0'
        else:res=digits[:point]+'.'+digits[point:]
        return ('-' if negative else '')+res
    if mant.endswith('.0'): mant=mant[:-2]
    return mant+'e'+str(exponent)


def rejecting_constant(s):
    raise ValueError('not a JSON number')

class Renderer:
    def __init__(self, enabled=None, disabled=None, builtin=True, custom=(), styles=None):
        self.groups=set(GROUPS if enabled is None else enabled)
        self.groups.difference_update(disabled or ())
        self.builtin=builtin
        self.styles=styles or default_styles()
        self.custom=[]
        for words,style in custom:
            self.custom.append((self.keyword_regex(words),style))
        self.layers=[]
        def add(group, pattern, formatter):
            if group in self.groups: self.layers.append((pattern,formatter))
        add('dates',DATE_RE,self.date)
        add('dates',TIME_RE,self.time)
        add('ip-addresses',V6_RE,self.ipv6)
        add('ip-addresses',V4_RE,self.ipv4)
        add('key-value-pairs',KV_RE,self.kv)
        add('urls',URL_RE,self.url)
        add('paths',PATH_RE,self.path)
        add('pointers',POINTER_RE,self.pointer)
        add('uuids',UUID_RE,self.uuid)
        add('processes',PROCESS_RE,self.process)
        add('numbers',NUMBER_RE,lambda m:self.paint('numbers','number',m[0]))
        if builtin:
            for words, style in [(['ERROR'],Style(fg='red')),(['WARN'],Style(fg='yellow')),
                                 (['DEBUG'],Style(fg='green')),(['TRACE'],Style(faint=True)),
                                 (['true','false','null'],Style(fg='red',italic=True)),
                                 (['GET'],Style(fg='black',bg='green')),
                                 (['POST'],Style(fg='black',bg='yellow')),
                                 (['PUT','PATCH'],Style(fg='black',bg='magenta')),
                                 (['DELETE'],Style(fg='black',bg='red'))]:
                self.layers.append((self.keyword_regex(words),lambda m, st=style: st.paint(m[0],pad=True)))
        for pattern,style in self.custom:
            self.layers.append((pattern,lambda m,st=style:st.paint(m[0],pad=True)))
        if builtin:
            self.layers.append((self.keyword_regex(['INFO']),lambda m: Style(fg='white').paint(m[0])))

    @staticmethod
    def keyword_regex(words):
        # A group with no words never matches.
        if not words:return re.compile(r'(?!)')
        return re.compile(r'(?<![A-Za-z0-9_])(?:'+'|'.join(re.escape(w) for w in words)+r')(?![A-Za-z0-9_])',ASCII)

    def paint(self,group,part,text):
        return self.styles[group][part].paint(text)

    def date(self,m):
        if m[1] is not None:
            y,a,d,b,e=m.group(1,2,3,4,5)
        else:
            d,a,e,b,y=m.group(6,7,8,9,10)
        p=lambda x:self.paint('dates','date',x)
        q=lambda x:self.paint('dates','separator',x)
        return p(y)+q(a)+p(d)+q(b)+p(e)

    def time(self,m):
        p=lambda x:self.paint('dates','time',x)
        q=lambda x:self.paint('dates','separator',x)
        z=lambda x:self.paint('dates','zone',x)
        out=z(m[1]) if m[1] else ''
        out+=p(m[2])+q(m[3])+p(m[4])+q(m[5])+p(m[6])
        if m[7]:out+=q(m[7])
        if m[8]:out+=p(m[8])
        if m[9]:out+=z(m[9])
        return out

    def ipv4(self,m):
        ip,slash,mask=m[0].partition('/')
        parts=ip.split('.')
        if any(int(x)>255 for x in parts) or (mask and int(mask)>32):
            return None
        p=lambda x:self.paint('ip_addresses','number',x)
        q=lambda x:self.paint('ip_addresses','separator',x)
        return q('.').join(map(p,parts))+(q('/')+p(mask) if slash else '')

    def ipv6(self,m):
        addr,slash,mask=m[0].partition('/')
        if ':' not in addr:return None
        try:ipaddress.IPv6Address(addr)
        except ValueError:return None
        if mask and int(mask)>128:return None
