                     +DAY+r')([-/])('+DAY+r')([-/])('+YEAR+r')')
TIME_RE = re.compile(r'([T\s]?)([01]?[0-9]|2[0-3])(:)([0-5][0-9])(:)([0-5][0-9])([.,:]?)([0-9]*)(Z?)', ASCII)
V4_RE = re.compile(r'\b[0-9]{1,3}(?:\.[0-9]{1,3}){3}\b(?:/[0-9]{1,2}\b)?',ASCII)
V6_RE = re.compile(r'[A-Fa-f0-9:.]{3,}(?:/[0-9]{1,3}\b)?',ASCII)
KV_RE = re.compile(r'(^|\s)([A-Za-z0-9_]+)(=)',ASCII)
PATH_RE = re.compile(r'(?:~|[A-Za-z0-9_.-]+|/)?(?:/[A-Za-z0-9_.-]+){2,}',ASCII)
POINTER_RE = re.compile(r'\b0[xX](?:[A-Fa-f0-9]{16}|[A-Fa-f0-9]{8})\b',ASCII)
UUID_RE = re.compile(r'\b[A-Fa-f0-9]{8}(?:-[A-Fa-f0-9]{4}){3}-[A-Fa-f0-9]{12}\b',ASCII)
PROCESS_RE = re.compile(r'([A-Za-z0-9_/-]+)\[([0-9]+)\]',ASCII)
NUMBER_RE = re.compile(r'\b[0-9]+(?:\.[0-9]+)?\b',ASCII)
URL_RE = re.compile(r'(https?)://([A-Za-z0-9_.-]+)(/[A-Za-z0-9_.~/%+\-]*)?([?&][A-Za-z0-9_.~%+?&=\-]*)?',ASCII)
