"""A dependency-free reader for the small TOML configuration vocabulary.

Source positions are carried through parsing so diagnostics point at the
configuration value, rather than merely at the containing table.
"""
import os
import re
import json
import textwrap
from dataclasses import dataclass
from .render import Style, COLORS, default_styles

@dataclass
class Node:
    value: object
    start: int
    end: int
    keys: dict = None

class ConfigError(Exception):
    def __init__(self, message, start=0, end=None):
        self.message=message
        self.start=start
        self.end=start+1 if end is None else end

class TomlReader:
    def __init__(self,text):
        self.text=text;self.i=0
        self.root=Node({},0,0,{})
        self.current=self.root
        self.explicit=set()

    def error(self,msg,start=None,end=None):
        raise ConfigError(msg,self.i if start is None else start,end)

    def skip(self,newlines=False):
        while self.i<len(self.text):
            c=self.text[self.i]
            if c in (' \t\r\n' if newlines else ' \t\r'):
                self.i+=1
            elif c=='#':
                end=self.text.find('\n',self.i)
                self.i=len(self.text) if end<0 else end
                if not newlines:return
            else:return

    def string(self):
        start=self.i;quote=self.text[self.i]
        multiline=self.text.startswith(quote*3,self.i)
        self.i+=3 if multiline else 1
        if multiline and self.text[self.i:self.i+1]=='\n':self.i+=1
        out=''
        while self.i<len(self.text):
            if self.text.startswith(quote*(3 if multiline else 1),self.i):
                self.i+=3 if multiline else 1
                return Node(out,start,self.i)
            c=self.text[self.i];self.i+=1
            if c=='\n' and not multiline:self.error('invalid basic string',self.i-1)
            if quote=='"' and c=='\\':
                if self.i==len(self.text):self.error('invalid escape sequence',self.i-1)
                code=self.text[self.i];self.i+=1
                conv={'b':'\b','t':'\t','n':'\n','f':'\f','r':'\r','"':'"','\\':'\\'}
                if code in conv:c=conv[code]
                elif code in 'uU':
                    n=4 if code=='u' else 8
                    h=self.text[self.i:self.i+n]
                    if not re.fullmatch('[0-9a-fA-F]{'+str(n)+'}',h):self.error('invalid unicode escape sequence')
                    self.i+=n
                    try:
                        v=int(h,16)
                        if 0xd800<=v<=0xdfff:raise ValueError()
                        c=chr(v)
                    except ValueError:self.error('invalid unicode scalar value',self.i-n)
                elif multiline and code in '\n\r \t':
                    while self.i<len(self.text) and self.text[self.i] in '\r\n \t':self.i+=1
                    c=''
                else:self.error('invalid escape sequence',self.i-1)
            out+=c
        self.error('invalid basic string' if quote=='"' else 'invalid literal string',self.i)

    def key(self):
        parts=[];positions=[]
        while True:
            self.skip();start=self.i
            if self.i>=len(self.text):self.error('empty key')
            if self.text[self.i] in '\'"':
                node=self.string();word=node.value;end=node.end
            else:
                m=re.match(r'[A-Za-z0-9_-]+',self.text[self.i:])
                if not m:self.error('invalid key')
                word=m[0];self.i+=len(word);end=self.i
            parts.append(word);positions.append((start,end));self.skip()
            if self.text[self.i:self.i+1]!='.':break
            self.i+=1
        return parts,positions

    def value(self):
        self.skip();start=self.i
        if self.i>=len(self.text):self.error('invalid string\nexpected `"`, `\'`')
        c=self.text[self.i]
        if c in '\'"':return self.string()
        if c=='[':
            self.i+=1;values=[]
            while True:
                self.skip(True)
                if self.text[self.i:self.i+1]==']':
                    self.i+=1;return Node(values,start,self.i)
                values.append(self.value());self.skip(True)
                if self.text[self.i:self.i+1]==',':self.i+=1;continue
                if self.text[self.i:self.i+1]!=']':self.error('invalid array\nexpected `]`')
        if c=='{':
            self.i+=1;result=Node({},start,start,{})
            self.skip()
            if self.text[self.i:self.i+1]=='}':self.i+=1;result.end=self.i;return result
            while True:
                parts,positions=self.key()
                if self.text[self.i:self.i+1]!='=':self.error('key with no value, expected `=`')
