                self.skip()
                if self.text[self.i:self.i+1]=='}':self.i+=1;result.end=self.i;return result
                if self.text[self.i:self.i+1]!=',':self.error('invalid inline table\nexpected `}`')
                self.i+=1
        m=re.match(r'[^\s,\]\}#]+',self.text[self.i:])
        if not m:self.error('invalid string\nexpected `"`, `\'`')
        token=m[0];self.i+=len(token)
        if token=='true':v=True
        elif token=='false':v=False
        elif re.fullmatch(r'[+-]?(?:0|[1-9](?:_?[0-9])*)',token):v=int(token.replace('_',''))
