    raise ConfigError('invalid type: '+type_name(node.value)+', expected '+expected,node.start,node.end)


def mapping(node,name,fields):
    if isinstance(node.value,dict):return node.value
    if isinstance(node.value,list):
        seq=node.value;n=len(fields)
        if len(seq)<n:
            raise ConfigError('invalid length '+str(len(seq))+', expected struct '+name+' with '+str(n)+' element'+('s' if n!=1 else ''),node.start,node.end)
        if len(seq)>n:
            raise ConfigError('invalid length '+str(len(seq))+', expected fewer elements in array',node.start,node.end)
        return dict(zip(fields,seq))
    bad_type(node,'struct '+name)


def parse_color(node):
    value=node.value
    if isinstance(value,dict):
        if len(value)!=1:
            raise ConfigError('wanted exactly 1 element, '+('found 0 elements' if not value else 'more than 1 element'),node.start,node.end)
        key=next(iter(value));n=value[key]
        span=node.keys.get(key,(node.start,node.end)) if node.keys else (node.start,node.end)
        if key not in COLORS:
            raise ConfigError('unknown variant `'+key+'`, expected one of '+', '.join('`'+x+'`' for x in COLORS),*span)
        if not isinstance(n.value,dict):
            t=type_name(n.value).split()[0]
            raise ConfigError('expected table, found '+t,n.start,n.end)
        return key
    if not isinstance(value,str):raise ConfigError('wanted string or table',node.start,node.end)
    if value not in COLORS:
        raise ConfigError('unknown variant `'+value+'`, expected one of '+', '.join('`'+x+'`' for x in COLORS),node.start,node.end)
    return value


def parse_style(node):
    fields=['fg','bg','bold','faint','italic','underline']
    data=mapping(node,'Style',fields)
    style=Style()
    for name,n in data.items():
        if name in ('fg','bg'):setattr(style,name,parse_color(n))
        elif name in ('bold','faint','italic','underline'):
            if not isinstance(n.value,bool):bad_type(n,'a boolean')
            setattr(style,name,n.value)
    return style

STRUCTS={'numbers':'NumberToml','urls':'UrlToml','pointers':'PointerToml',
         'dates':'DateToml','paths':'PathToml','quotes':'QuotesToml',
         'key_value_pairs':'KeyValueToml','uuids':'UuidToml',
         'ip_addresses':'IpToml','processes':'UnixProcessToml','json':'JsonToml'}


def theme_from_text(text):
    root=TomlReader(text).parse().value
    styles=default_styles();keywords=[]
    for group,node in root.items():
        if group in STRUCTS:
            fields=list(styles[group])
            if group=='json':fields.remove('quotes')
            table=mapping(node,STRUCTS[group],fields)
            for part,stylenode in table.items():
                if part in fields:styles[group][part]=parse_style(stylenode)
        elif group=='keywords':
            if not isinstance(node.value,list):bad_type(node,'a sequence')
            for kw in node.value:
                data=mapping(kw,'KeywordToml',['words','style'])
                words=None;style=None
                for key,value in data.items():
                    if key=='words':
                        if not isinstance(value.value,list):bad_type(value,'a sequence')
                        words=[]
                        for word in value.value:
                            if not isinstance(word.value,str):bad_type(word,'a string')
                            words.append(word.value)
                    elif key=='style':style=parse_style(value)
                if words is None:raise ConfigError('missing field `words`',kw.start,kw.end)
                if style is None:raise ConfigError('missing field `style`',kw.start,kw.end)
                keywords.append((words,style))
    return styles,keywords


def config_diagnostic(text,error):
    start=min(error.start,len(text));line=text.count('\n',0,start)+1
    begin=text.rfind('\n',0,start)+1;col=start-begin+1
    end=text.find('\n',begin)
    if end<0:end=len(text)
    excerpt=text[begin:end].rstrip('\r')
    count=max(1,min(error.end,end)-start)
    margin=' '*len(str(line))
    lines=['Error:   × TOML parse error at line '+str(line)+', column '+str(col),
           '  │ '+margin+' |', '  │ '+str(line)+' | '+excerpt,
           '  │ '+margin+' | '+' '*(col-1)+'^'*count]
    for paragraph in error.message.split('\n'):
        wrapped=textwrap.wrap(paragraph,width=74,break_long_words=False,break_on_hyphens=False) or ['']
        lines.extend('  │ '+s for s in wrapped)
    return '\n'.join(lines)+'\n  │ \n\n'
