NAMES={'follow':'--follow','print':'--print','config-path':'--config-path <CONFIG_PATH>',
       'exec':'--exec <EXEC>','highlight':'--highlight <COLOR_WORD>',
       'enable':'--enable <ENABLED_HIGHLIGHTERS>','disable':'--disable <DISABLED_HIGHLIGHTERS>',
       'disable-builtin-keywords':'--disable-builtin-keywords','pager':'--pager <PAGER>',
       'help':'--help','version':'--version'}
FLAGS={'follow','print','disable-builtin-keywords','help','version'}
REPEATABLE={'highlight','enable','disable'}
SHORT={'f':'follow','p':'print','e':'exec','h':'help','V':'version'}
VALUES='  [possible values: '+', '.join(GROUPS)+']\n'
FOOTER="For more information, try '--help'.\n"

class Exit(Exception):
    def __init__(self,code,text='',stderr=False):self.code=code;self.text=text;self.stderr=stderr


def general_error(message):
    raise Exit(1,'Error:   × '+message+'\n\n',True)


def similar(value,choices):
    answer=difflib.get_close_matches(value,choices,n=1,cutoff=.6)
    return answer[0] if answer else None


def parse_args(argv,prog):
    result={'file':None,'follow':False,'print':False,'disable-builtin-keywords':False,
            'config-path':None,'exec':None,'pager':None,'enable':None,'disable':[], 'highlight':[]}
    used=set()
    usage='Usage: '+prog+' [OPTIONS] [FILE]\n'
    def fail(msg,extra='',with_usage=True,custom_usage=None):
        text='error: '+msg+'\n'+extra
        if with_usage:text+='\n'+(custom_usage or usage)
        text+='\n'+FOOTER
        raise Exit(2,text,True)
    def missing(name):
        fail("a value is required for '"+NAMES[name]+"' but none was supplied",VALUES if name in ('enable','disable') else '',False)
    def assign(name,value,form):
        if name=='help':
            template=HELP_LONG if form=='--help' else HELP_SHORT
            raise Exit(0,template.format(prog=prog,pager=os.environ.get('TAILSPIN_PAGER','')))
        if name=='version':raise Exit(0,'tspin 5.6.0\n')
        if name in used and name not in REPEATABLE:
            fail("the argument '"+NAMES[name]+"' cannot be used multiple times")
        used.add(name)
        if name in FLAGS:
            result[name]=True;return
        if name in ('enable','disable'):
            groups=value.split(',')
            for group in groups:
                if not group:missing(name)
                if group not in GROUPS:
                    suggestion=similar(group,GROUPS)
                    extra=VALUES
                    if suggestion:extra+="\n  tip: a similar value exists: '"+suggestion+"'\n"
                    fail("invalid value '"+group+"' for '"+NAMES[name]+"'",extra,False)
            if result[name] is None:result[name]=[]
            result[name].extend(groups)
        elif name=='highlight':
            if ':' not in value:
                fail("invalid value '"+value+"' for '"+NAMES[name]+"': Expected format COLOR:word1,word2,... found `"+value+'`','',False)
            color,words=value.split(':',1)
            if color.lower() not in ('red','green','yellow','blue','magenta','cyan'):
                fail("invalid value '"+value+"' for '"+NAMES[name]+"': invalid variant: "+color,'',False)
            result[name].append((words.split(','),Style(fg=color.lower())))
        else:
            if name=='config-path' and not value:missing(name)
            result[name]=value
    i=0;end_options=False
    while i<len(argv):
        token=argv[i];i+=1
        if not end_options and token=='--':end_options=True;continue
        if not end_options and token.startswith('--'):
            name,equals,value=token[2:].partition('=')
            if name not in NAMES:
                suggestion=similar(name,NAMES)
                if name=='color':suggestion='follow'
                if suggestion:
                    extra="\n  tip: a similar argument exists: '--"+suggestion+"'\n"
                    fail("unexpected argument '"+token+"' found",extra,True,'Usage: '+prog+' '+NAMES[suggestion]+' [FILE]\n')
                fail("unexpected argument '"+token+"' found","\n  tip: to pass '"+token+"' as a value, use '-- "+token+"'\n")
            if name in FLAGS:
                if equals:
                    fail("unexpected value '"+value+"' for '--"+name+"' found; no more were expected",'',True,'Usage: '+prog+' '+NAMES[name]+' [FILE]\n')
                assign(name,None,token);continue
            if not equals:
                if i>=len(argv) or (argv[i].startswith('-') and argv[i]!='-'):missing(name)
                value=argv[i];i+=1
            assign(name,value,'--'+name)
        elif not end_options and token.startswith('-') and token!='-':
            j=1
            while j<len(token):
                char=token[j];j+=1
                if char not in SHORT:
                    unknown='-'+char
                    fail("unexpected argument '"+unknown+"' found","\n  tip: to pass '"+unknown+"' as a value, use '-- "+unknown+"'\n")
                name=SHORT[char]
                if name in FLAGS:assign(name,None,'-'+char)
                else:
                    if j<len(token):value=token[j:].lstrip('=');j=len(token)
                    else:
                        if i>=len(argv) or (argv[i].startswith('-') and argv[i]!='-'):missing(name)
                        value=argv[i];i+=1
                    assign(name,value,'-'+char)
        else:
            if result['file'] is not None:fail("unexpected argument '"+token+"' found")
            result['file']=token
