            raise Exit(1,'Error:   ⚠ \x1b[33m'+filename+'\x1b[0m: '+reason+'\n\n',True)
        if not stat.S_ISREG(s.st_mode):general_error('Path is not a file')
    if filename is not None and options['exec'] is not None:
        general_error('Cannot read from both file and \x1b[35m--listen-command\x1b[0m')
    if options['enable'] is not None and options['disable']:
        general_error('cannot both enable and disable highlighters')
    explicit=options['config-path'] is not None
    path=options['config-path']
    if path is None:
        root=os.environ.get('XDG_CONFIG_HOME') or os.path.join(os.path.expanduser('~'),'.config')
        path=os.path.join(root,'tailspin','theme.toml')
    styles=None;custom=[]
    if os.path.exists(path):
        try:
            with open(path,'r',encoding='utf-8') as f:text=f.read()
        except (OSError,UnicodeError) as e:
            if isinstance(e,OSError):reason=e.strerror+' (os error '+str(e.errno)+')'
            else:reason='stream did not contain valid UTF-8'
            raise Exit(1,'Error:   × could not read the TOML file: '+reason+'\n  ╰─▶ '+reason+'\n\n',True)
