    return Renderer(options['enable'],options['disable'],not options['disable-builtin-keywords'],custom,styles)


def output(text):
    sys.stdout.buffer.write(text.encode('utf-8'))
    sys.stdout.buffer.flush()


def stream(reader,renderer,sink=output):
    while True:
        raw=reader.readline()
        if not raw:break
        try:text=raw.decode('utf-8')
        except UnicodeError:general_error('stream did not contain valid UTF-8')
        if text.endswith('\n'):text=text[:-1]
        sink(renderer.line(text)+'\n')


def read_file(path,renderer):
    try:
        with open(path,'rb') as f:raw=f.read()
        text=raw.decode('utf-8')
    except UnicodeError:
        raise Exit(1,'Error:   × Failed to receive initial-read-complete signal\n  ╰─▶ channel closed\n  help: Ensure the IO task completes correctly and signals initial read\n        completion.\n\n',True)
    except OSError as e:general_error(e.strerror+' (os error '+str(e.errno)+')')
    pieces=text.split('\n')
    completed=pieces[:-1];partial=pieces[-1]
    first=''.join(renderer.line(s[:-1] if s.endswith('\r') else s)+'\n' for s in completed)
    if not completed:first='\n'
    remainder=renderer.line(partial)+'\n' if partial else ''
    return first,remainder,len(raw)


def pager_args(options,path):
    command=options['pager']
    if command is None:command=os.environ.get('TAILSPIN_PAGER')
    if command is not None:
        try:parts=shlex.split(command)
        except ValueError:general_error('Could not parse custom pager command')
        if len(parts)<2:general_error('Could not parse custom pager command')
        return [part.replace('[FILE]',path) for part in parts]
    # The pager is an ordinary system utility, not a highlighting dependency.
    return ['less','-R','+F' if options['follow'] else '-F',path]


def run_pager(text,options):
    with tempfile.TemporaryDirectory(prefix='tailspin-') as folder:
        path=os.path.join(folder,'output.log')
        with open(path,'w',encoding='utf-8',newline='') as f:f.write(text)
        args=pager_args(options,path)
        try:p=subprocess.run(args)
        except OSError as e:
            raise Exit(1,'Error: less::command_spawn\n\n  × Could not run pager\n  ╰─▶ '+e.strerror+' (os error '+str(e.errno)+')\n\n',True)
        if p.returncode:
            status='exit status: '+str(p.returncode) if p.returncode>0 else 'signal: '+str(-p.returncode)
            raise Exit(1,'Error: less::non_zero_exit\n\n  × Pager exited with non-zero status: '+status+'\n\n',True)


def follow_file(path,pos,renderer,sink=output):
    pending=b''
    old_inode=None
    try:old_inode=os.stat(path).st_ino
    except OSError:pass
    while True:
        time.sleep(.08)
        try:
            st=os.stat(path)
            if old_inode!=st.st_ino or st.st_size<pos:
                pos=0;pending=b'';old_inode=st.st_ino
            if st.st_size<=pos:continue
            with open(path,'rb') as f:
                f.seek(pos);chunk=f.read();pos=f.tell()
        except OSError:continue
        pending+=chunk
        while b'\n' in pending:
            line,pending=pending.split(b'\n',1)
            if line.endswith(b'\r'):line=line[:-1]
            try:text=line.decode('utf-8')
            except UnicodeError:general_error('stream did not contain valid UTF-8')
            sink(renderer.line(text)+'\n')


def run(options):
    renderer=load_renderer(options)
    if options['file'] is not None:
        first,rest,pos=read_file(options['file'],renderer)
        if options['print']:
            output(first)
            if options['follow']:
                output(rest)
                follow_file(options['file'],pos,renderer)
        elif options['follow']:
            # Feed updates to the pager's ordinary file as well as the initial
            # snapshot. The writer lives only while the pager is running.
            import threading
            with tempfile.TemporaryDirectory(prefix='tailspin-') as folder:
                path=os.path.join(folder,'output.log')
                with open(path,'w',encoding='utf-8') as f:f.write(first+rest)
                def append(s):
                    try:
                        with open(path,'a',encoding='utf-8') as f:f.write(s)
                    except OSError:pass
                worker=threading.Thread(target=follow_file,args=(options['file'],pos,renderer,append),daemon=True)
                worker.start()
                try:p=subprocess.run(pager_args(options,path))
                except OSError as e:raise Exit(1,'Error: less::command_spawn\n\n  × Could not run pager\n  ╰─▶ '+e.strerror+' (os error '+str(e.errno)+')\n\n',True)
                if p.returncode:raise Exit(1,'Error: less::non_zero_exit\n\n  × Pager exited with non-zero status: exit status: '+str(p.returncode)+'\n\n',True)
        else:run_pager(first+rest,options)
    elif not sys.stdin.isatty():
        stream(sys.stdin.buffer,renderer)
    elif options['exec'] is not None:
        process=subprocess.Popen(options['exec'],shell=True,stdout=subprocess.PIPE)
        if options['print']:
            stream(process.stdout,renderer);process.wait()
        else:
            rendered=[];stream(process.stdout,renderer,rendered.append);process.wait()
            run_pager(''.join(rendered),options)
    else:output('Missing filename (\x1b[36mtspin --help\x1b[0m for help)\n')
    return 0


def main():
    # Keep the installed invocation name in clap-style diagnostics.
    prog=os.path.basename(sys.argv[0])
    if prog in ('cli.py','__main__.py'):prog='executable'
    code=0
    try:
        options=parse_args(sys.argv[1:],prog)
        code=run(options)
    except Exit as e:
        target=sys.stderr if e.stderr else sys.stdout
        target.write(e.text);target.flush();code=e.code
    except KeyboardInterrupt:
        code=0
    except BrokenPipeError:
